const { TaskList, TaskItem } = await import("@tiptap/extension-list");
const { default: Image } = await import("@tiptap/extension-image");

const tableEdgeCases: Case[] = [
	{
		id: "t-escaped-pipe",
		group: "table",
		label: "单元格里转义的竖线 \\|",
		md: "| 表达式 | 含义 |\n| --- | --- |\n| a \\| b | 或 |\n",
